using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;

    private HttpStatusCode replyStatus = HttpStatusCode.OK;
    private string replyBody = """{"status":"approved"}""";
    private string? seenMethod, seenPath, seenContentType, seenBody;

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        listener.Start();
        _ = Task.Run(Serve);
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    [Fact]
    public async Task Sends_a_json_post_with_reference_amount_and_currency()
    {
        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal("POST", seenMethod);
        Assert.Equal("/v1/authorizations", seenPath);
        Assert.StartsWith("application/json", seenContentType);
        using var json = JsonDocument.Parse(seenBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_declined()
    {
        replyBody = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        replyBody = """{"id":"x1","status":"approved","score":0.3}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_declined_whatever_the_body()
    {
        replyStatus = HttpStatusCode.PaymentRequired;
        replyBody = """{"error":"card_refused"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_declined()
    {
        replyStatus = HttpStatusCode.PaymentRequired;
        replyBody = "";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_exactly_approved_is_never_approved(string body)
    {
        replyBody = body;
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("")]
    [InlineData("not json")]
    [InlineData("""{"status":""")]
    public async Task An_unreadable_answer_fails_loudly(string body)
    {
        replyBody = body;
        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.UnprocessableEntity)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_error_statuses_are_raised_not_treated_as_declines(HttpStatusCode status)
    {
        replyStatus = status;
        replyBody = """{"status":"approved"}""";
        var ex = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal(status, ex.StatusCode);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); }
            catch { return; }

            using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8))
                seenBody = await reader.ReadToEndAsync();
            seenMethod = ctx.Request.HttpMethod;
            seenPath = ctx.Request.Url!.AbsolutePath;
            seenContentType = ctx.Request.ContentType;

            var bytes = Encoding.UTF8.GetBytes(replyBody);
            ctx.Response.StatusCode = (int)replyStatus;
            ctx.Response.ContentType = "application/json";
            ctx.Response.ContentLength64 = bytes.Length;
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private static int FreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
